head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
scwin.trigger1_onclick = function(e) {
    generator1.removeAll();
};
scwin.trigger2_onclick = function(e) {
    generator1.insertChild();
};
scwin.trigger4_onclick = function(e) {
    for (var i = 0; i < generator1.getLength(); i++) {
        console.log(i);
        fwGaugeChart1ObjGen = generator1.getChild(i, "fwGaugeChart1");
        //fwGaugeChart1ObjGen.remove();
        generator1.removeChild(i);
    }
};
scwin.trigger5_onclick = function(e) {
    generator1.insertChild();
};
scwin._checkHtml = function() {
    return ((j) => j.length ? j : $('#mf_generator1'))($('#generator1')).html();
}
scwin._hasError = function() {
    var log = WebSquare.logger.getErrorLog();
    return log;
}
scwin.checktype = function() {
    //return typeof generator1_0_fwGaugeChart1;
